import React, { useEffect, useState } from 'react'
import {
  Icon,
  Row,
  Form,
  Modal,
  Table,
  Button,
  Input,
  notification,
  Spin
} from 'antd'
import {
  BackBtn,
  CancelBtn,
  DetailTabWrapper,
  LayoutContentStyle,
  LayoutWrapper,
  ReportConfigStyleWrapper,
  SaveBtn,
  TabsHeader
} from '../index.style'
import { connect } from 'react-redux'
import { getFormItems } from '../helpers/formItems'
import { addFormData, reportTypeOptions } from '../helpers/data'
import productconfigActions from '../../../redux/productConfig/actions'
import { capitalizeFirstLetter } from '../../../../helpers/utility'
import reportingconfigActions from '../../../redux/reportingConfig/actions'
import policyActions from '../../../../redux/policy/actions'
import providerAction from '../../../redux/provider/actions'

const { TextArea } = Input
const { getProductList, productDetailPackges } = productconfigActions
const { createReportingConfig, resetReportingConfigRedux } =
  reportingconfigActions
const { getPartners } = policyActions
const { getProviderList } = providerAction

const initialData = [{ key: 'sql', description: '' }]

const ReportingConfigDetail = (props) => {
  const {
    getProductList,
    productList,
    getPartners,
    getProviderList,
    productDetailPackges,
    createReportingConfig,
    productDetailPackagesData,
    createReportingConfigMessage,
    resetReportingConfigRedux,
    productListLoading = false,
    productDetailPackagesLoading = false,
    partners,
    providerList
  } = props
  const [descriptionData, setDescriptionData] = useState(initialData)
  const [product, setproducts] = useState([])
  const [pkg, setPkg] = useState([])
  const [partnerData, setPartner] = useState([])
  const [providerData, setProvider] = useState([])

  useEffect(() => {
    getProductList({ query: {} })
    getPartners()
    getProviderList()
  }, [])

  useEffect(() => {
    if (productList?.data?.details) {
      const transformed = productList?.data?.details?.map((item) => ({
        key: item.code,
        value: item.name
      }))
      setproducts(transformed)
    }
  }, [productList])

  useEffect(() => {
    if (productDetailPackagesData?.data?.details) {
      const transformed = productDetailPackagesData?.data?.details?.map(
        (item) => ({
          key: item.code,
          value: item.name
        })
      )
      setPkg(transformed)
    }
  }, [productDetailPackagesData])

  useEffect(() => {
    if (partners && partners.length) {
      const transformed = partners.map((item) => ({
        key: item.code,
        value: item.name
      }))
      setPartner(transformed)
    }
  }, [partners])

  useEffect(() => {
    if (providerList && providerList.length) {
      const transformed = providerList.map((item) => ({
        key: item.code,
        value: item.name
      }))
      setProvider(transformed)
    }
  }, [providerList])

  useEffect(() => {
    const { history } = props
    if (
      createReportingConfigMessage &&
      createReportingConfigMessage === 'success'
    ) {
      notification.success({ message: 'Config Created Succesfully!' })
      resetReportingConfigRedux(['createReportingConfigMessage'])
      history.push('/reporting-config')
    }
  }, [createReportingConfigMessage])

  useEffect(() => {
    if (props.form.getFieldValue('product_key')) {
      setPkg([])
      productDetailPackges({
        query: { productCode: props.form.getFieldValue('product_key') }
      })
    }
  }, [props.form.getFieldValue('product_key')])
  useEffect(() => {
    if (props.form.getFieldValue('for')) {
      props.form.setFieldsValue({
        target: ''
      })
    }
  }, [props.form.getFieldValue('for')])

  const handleTextChange = (e, key) => {
    const updatedData = descriptionData.map((item) =>
      item.key === key ? { ...item, description: e.target.value } : item
    )
    setDescriptionData(updatedData)
  }

  const handleOnBackData = () => {
    const { history } = props
    history.push('/reporting-config')
  }

  const handleCancel = () => {
    Modal.confirm({
      title: 'Are you sure you want to cancel',
      okText: 'OK',
      cancelText: 'Cancel',
      onOk: handleOnBackData
    })
  }

  const handleSubmit = () => {
    props.form.validateFields((err, values) => {
      const emailInternal = {}
      const emailExternal = {};
      (values.recipients_internal || []).forEach((item) => {
        if (item.email && item.name) {
          emailInternal[item.email] = item.name
        }
      });
      (values.recipients_external || []).forEach((item) => {
        if (item.email && item.name) {
          emailExternal[item.email] = item.name
        }
      })
      if (!err) {
        const payload = {
          ...values,
          status: 'Active',
          sql: descriptionData[0].description,
          recipients_internal: emailInternal,
          recipients_external: emailExternal,
          start_date: values.start_date
            ? values.start_date.format('YYYY-MM-DD')
            : null
        }
        createReportingConfig(payload)
      }
    })
  }

  const columns = [
    {
      title: 'SQL Query',
      dataIndex: 'description',
      key: 'description',
      render: (text, record) => (
        <TextArea
          value={record.description}
          rows={4}
          onChange={(e) => handleTextChange(e, record.key)}
          placeholder='Enter description...'
        />
      )
    },
    {
      title: 'Actions',
      key: 'actions',
      width: 150,
      render: () => (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <Button
            style={{ fontWeight: '800', textAlign: 'left' }}
            type='link'
            disabled
          >
            View
          </Button>
          <Button
            style={{ fontWeight: '800', textAlign: 'left' }}
            type='link'
            disabled
          >
            Edit
          </Button>
          <Button
            style={{ fontWeight: '800', textAlign: 'left' }}
            type='link'
            disabled
          >
            Delete
          </Button>
        </div>
      )
    }
  ]

  const handleSubmitFormModal = (record) => {
    Modal.confirm({
      title: <p>Are you sure you want to Submit Form?</p>,
      okText: 'OK',
      cancelText: 'Cancel',
      onOk: handleSubmit
    })
  }

  return (
    <LayoutWrapper>
      <BackBtn onClick={handleOnBackData}>
        <Icon type='left' style={{ fontSize: '24px', marginRight: 8 }} />
        <div style={{ fontSize: '24px', fontWeight: '800' }}>Add Report</div>
      </BackBtn>
      <Form hideRequiredMark>
        <LayoutContentStyle borderRadius='16px'>
          <ReportConfigStyleWrapper>
            <TabsHeader>General Details</TabsHeader>

            <DetailTabWrapper>
              {Object.keys(addFormData.general_details).map((item) => {
                if (addFormData.general_details[item] && item === 'target') {
                  const forLabel = props.form.getFieldValue('for')
                  const optionsdata =
                    forLabel === 'Partner'
                      ? partnerData
                      : forLabel === 'Provider'
                        ? providerData
                        : addFormData.general_details[item].options
                  return getFormItems(
                    {
                      fieldName: item,
                      type: {
                        ...addFormData.general_details[item],
                        options: optionsdata
                      },
                      disabled: !forLabel,
                      label: capitalizeFirstLetter(item),
                      initialValue: {},
                      required: true
                    },
                    props.form
                  )
                }

                if (
                  addFormData.general_details[item] &&
                  item === 'report_type'
                ) {
                  const via = props.form.getFieldValue('report_via')
                  const optionsdata =
                    via === 'EMAIL'
                      ? reportTypeOptions.EMAIL
                      : via === 'SFTP'
                        ? reportTypeOptions.SFTP
                        : addFormData.general_details[item].options

                  return getFormItems(
                    {
                      fieldName: item,
                      type: {
                        ...addFormData.general_details[item],
                        options: optionsdata
                      },
                      disabled: !via,
                      label: capitalizeFirstLetter(item),
                      initialValue: {},
                      required: true
                    },
                    props.form
                  )
                }

                if (item === 'subject_line') {
                  const via = props.form.getFieldValue('report_via')
                  if (via === 'EMAIL') {
                    return getFormItems(
                      {
                        fieldName: item,
                        type: addFormData.general_details[item],
                        label: 'Subject Line',
                        initialValue: {},
                        required: true
                      },
                      props.form
                    )
                  }
                  return null
                }

                if (addFormData.general_details[item]) {
                  return getFormItems(
                    {
                      fieldName: item,
                      type: addFormData.general_details[item],
                      label: capitalizeFirstLetter(item),
                      initialValue: {},
                      required: true
                    },
                    props.form
                  )
                }

                return null
              })}
            </DetailTabWrapper>
          </ReportConfigStyleWrapper>
        </LayoutContentStyle>

        <LayoutContentStyle borderRadius='16px'>
          <ReportConfigStyleWrapper>
            <TabsHeader>Report Distribution</TabsHeader>
            <DetailTabWrapper>
              {Object.keys(addFormData.report_distribution).map((item) => {
                if (
                  addFormData.report_distribution[item] &&
                  item === 'trigger_period'
                ) {
                  const triggerFrequency =
                    props.form.getFieldValue('trigger_frequency')
                  if (triggerFrequency === 'Daily') return null
                  if (triggerFrequency === 'monthly') {
                    return getFormItems(
                      {
                        fieldName: item,
                        type: {
                          ...addFormData.report_distribution[item],
                          type: 'calendar'
                        },
                        label: capitalizeFirstLetter(
                          addFormData.report_distribution[item].field_name
                        ),
                        initialValue: {},
                        required: true
                      },
                      props.form
                    )
                  }
                  return getFormItems(
                    {
                      fieldName: item,
                      type: addFormData.report_distribution[item],
                      label: capitalizeFirstLetter(
                        addFormData.report_distribution[item].field_name
                      ),
                      initialValue: {},
                      required: true
                    },
                    props.form
                  )
                }
                if (addFormData.report_distribution[item]) {
                  return getFormItems(
                    {
                      fieldName: item,
                      type: addFormData.report_distribution[item],
                      label: capitalizeFirstLetter(
                        addFormData.report_distribution[item].field_name
                      ),
                      initialValue: {},
                      required: true
                    },
                    props.form
                  )
                }
                return null
              })}
            </DetailTabWrapper>
          </ReportConfigStyleWrapper>
        </LayoutContentStyle>
        <LayoutContentStyle borderRadius='16px'>
          <ReportConfigStyleWrapper>
            <TabsHeader>Report Template</TabsHeader>
            <Table
              dataSource={descriptionData}
              columns={columns}
              pagination={false}
              rowKey='key'
            />
          </ReportConfigStyleWrapper>
        </LayoutContentStyle>

        <LayoutContentStyle borderRadius='16px'>
          <ReportConfigStyleWrapper>
            <TabsHeader>Report Query</TabsHeader>
            <Spin spinning={productListLoading || productDetailPackagesLoading}>
              <DetailTabWrapper>
                {Object.keys(addFormData.report_query).map((item) => {
                  if (
                    addFormData.report_query[item] &&
                    item === 'product_key'
                  ) {
                    return getFormItems(
                      {
                        fieldName: item,
                        type: {
                          ...addFormData.report_query[item],
                          options: product
                        },
                        label: capitalizeFirstLetter(item),
                        initialValue: {},
                        required: true,
                        isMultiple: true
                      },
                      props.form
                    )
                  }
                  if (
                    addFormData.report_query[item] &&
                    item === 'package_name'
                  ) {
                    const isProductSelected =
                      !!props.form.getFieldValue('product_key') && pkg.length
                    return getFormItems(
                      {
                        fieldName: item,
                        type: {
                          ...addFormData.report_query[item],
                          options: pkg
                        },
                        disabled: !isProductSelected,
                        label: capitalizeFirstLetter(item),
                        initialValue: {},
                        required: true,
                        isMultiple: true
                      },
                      props.form
                    )
                  }
                  if (addFormData.report_query[item]) {
                    return getFormItems(
                      {
                        fieldName: item,
                        type: addFormData.report_query[item],
                        label: capitalizeFirstLetter(item),
                        initialValue: {},
                        required: true
                      },
                      props.form
                    )
                  }
                  return null
                })}
              </DetailTabWrapper>
            </Spin>
          </ReportConfigStyleWrapper>
        </LayoutContentStyle>

        <Row type='flex' justify='end' style={{ marginTop: 24 }}>
          <CancelBtn style={{ marginRight: '32px' }} onClick={handleCancel}>
            Cancel
          </CancelBtn>
          <SaveBtn type='primary' onClick={handleSubmitFormModal}>
            Save
          </SaveBtn>
        </Row>
      </Form>
    </LayoutWrapper>
  )
}

const WrappedReportingConfigDetail = Form.create()(ReportingConfigDetail)

export default connect(
  (state) => ({
    productList: state.ProductConfigurable.productList,
    productListMessage: state.ProductConfigurable.productListMessage,
    productListLoading: state.Loading.GET_PRODUCT_LIST,
    productListError: state.Error.GET_PRODUCT_LIST,

    productDetailPackagesData: state.ProductConfigurable.productDetailPackges,
    productDetailPackagesMessage:
      state.ProductConfigurable.productDetailPackgesMessage,
    productDetailPackagesLoading: state.Loading.GET_PRODUCT_PACKGES,
    productDetailPackagesError: state.Error.GET_PRODUCT_PACKGES,

    partners: state.Insurance.partners,
    providerList: state.Provider.providerList,

    createReportingConfigMessage:
      state.ReportingConfigurable.createReportingConfigMessage,
    createReportingConfigLoading: state.Error.CREATE_REPORTING_CONFIG_DETAILS
  }),
  {
    getProductList,
    productDetailPackges,
    createReportingConfig,
    getPartners,
    resetReportingConfigRedux,
    getProviderList
  }
)(WrappedReportingConfigDetail)
